-- Reproduction des tables BSH concernées, telles qu'en production le 23/11/2026 (colonnes, contraintes, règles d'accès,
-- déclencheur bsh_garde_mission), relevées par lecture du catalogue. À charger après ../0129_secret_stories/1_environnement_supabase_minimal.sql.
create table if not exists auth.users (id uuid primary key);
create table public.bsh_agenda_reglages (id integer default 1 not null primary key check (id = 1), fuseau text default 'America/Cayenne' not null, horaires_principaux text[] default array['08:00','21:00'] not null, pensee_actif boolean default true not null, pensee_frequence_jours integer default 2 not null, pensee_heure text default '08:00' not null, pensee_date_reference date default '2026-11-16' not null, updated_at timestamptz default now() not null);
create table public.bsh_campagnes (id uuid default gen_random_uuid() primary key, nom text not null, saison text default 'autre' not null check (saison in ('noel','saint_valentin','paques','toussaint','anniversaire_bsh','autre')), description text, date_debut date, date_fin date, date_cible timestamptz, recurrence_annuelle boolean default true not null, couleur_principale text, couleur_secondaire text, visuel_url text, statut text default 'brouillon' not null check (statut in ('brouillon','preparation','active','terminee','archivee')), notes_internes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.bsh_jeux (id uuid default gen_random_uuid() primary key, nom text not null, description text, icone text default '🎴' not null, type_jeu text default 'cartes_defis' not null, intensite text default 'audace' not null, statut text default 'brouillon' not null check (statut in ('brouillon','en_attente','programme','publie','suspendu','archive')), ordre integer default 0 not null, created_at timestamptz default now() not null, updated_at timestamptz default now() not null, mode text default 'communautaire' not null, choix_categories text[]);
create table public.bsh_hotes (id uuid default gen_random_uuid() primary key, nom text, prenom text, telephone text, email text, statut text default 'candidature' not null check (statut in ('candidature','active','inactive','refusee')), disponibilites text, notes_internes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null, profile_id uuid, pseudo_scene text, ville text, langues text[] default '{}' not null, competences text[] default '{}' not null, presentation text, majeur_confirme boolean default false not null, identite_verifiee boolean default false not null, statut_juridique text, conditions_validees boolean default false not null, charte_signee_le timestamptz, autorise_missions boolean default false not null, autorise_remuneration boolean default false not null, permissions jsonb default '{}' not null);
create or replace function public.bsh_mon_hote() returns uuid language sql stable security definer set search_path = public as $$ select id from public.bsh_hotes where profile_id = auth.uid() and statut = 'active' limit 1 $$;
create table public.bsh_hotes_disponibilites (id uuid default gen_random_uuid() primary key, hote_id uuid not null, jour date not null, debut time, fin time, type text default 'disponible' not null check (type in ('disponible','indisponible')), note text, created_at timestamptz default now() not null);
create table public.bsh_communications (id uuid default gen_random_uuid() primary key, titre text not null, contenu text not null, type text default 'annonce' not null check (type in ('annonce','notification','publication')), cible text default 'tous' not null check (cible in ('tous','clientes','hotesses','fondatrice')), statut text default 'brouillon' not null check (statut in ('brouillon','en_attente','valide','programme','pret','publie','reporte','annule','archive')), created_at timestamptz default now() not null, publiee_le timestamptz, espace text check (espace in ('chaine','cercle','lounge')), date_programmee timestamptz, jeu_id uuid, visuel_url text, lien_externe text, thematique text, fuseau text default 'America/Cayenne' not null, hote_id uuid, notes_internes text, date_publication_effective timestamptz, creneau text, campagne_id uuid, serie_id uuid, recurrence jsonb, rappel_le timestamptz, updated_at timestamptz default now() not null);
create table public.bsh_animations (id uuid default gen_random_uuid() primary key, nom text not null, categorie text default 'quiz' not null, regles text, difficulte text default 'moyen' not null, duree_minutes integer, participants_min integer, participants_max integer, questions jsonb default '[]' not null, points_actifs boolean default false not null, jeu_id uuid, hote_id uuid, campagne_id uuid, date_prevue timestamptz, espace text check (espace in ('chaine','cercle','lounge','evenement')), statut text default 'brouillon' not null, notes_internes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.bsh_missions (id uuid default gen_random_uuid() primary key, hote_id uuid not null, titre text not null, description text, date_mission timestamptz, lieu text, remuneration numeric, statut text default 'proposee' not null check (statut in ('proposee','acceptee','refusee','confirmee','terminee','annulee')), created_at timestamptz default now() not null, updated_at timestamptz default now() not null, evenement_id uuid, role_mission text, heure_debut time, heure_fin time, consignes text, simulation boolean default true not null, reponse_hote text, reponse_le timestamptz);
create table public.bsh_rewards_campagnes (id uuid default gen_random_uuid() primary key, titre text not null, statut text default 'brouillon' not null, participation_ouverte boolean default false not null, campagne_id uuid, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.events_medias (id uuid default gen_random_uuid() primary key, url text not null, chemin_storage text not null, nom_fichier text not null, dossier text default '' not null, created_at timestamptz default now() not null);
create or replace function public.est_hote_bsh() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.bsh_hotes where profile_id = auth.uid() and statut = 'active') $$;
do $$ declare t text; begin foreach t in array array['bsh_agenda_reglages','bsh_campagnes','bsh_jeux','bsh_hotes','bsh_hotes_disponibilites','bsh_communications','bsh_animations','bsh_missions','bsh_rewards_campagnes','events_medias'] loop execute format('alter table public.%I enable row level security', t); end loop; end $$;
create policy bsh_hotes_fondatrice on public.bsh_hotes for all to public using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_hotes_propre_fiche on public.bsh_hotes for select to authenticated using (profile_id = auth.uid());
create policy bsh_communications_clientes on public.bsh_communications for select to authenticated using (statut = 'publie' and cible = 'clientes');
create policy bsh_communications_fondatrice on public.bsh_communications for all to public using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_communications_hote_attribuee on public.bsh_communications for select to authenticated using (hote_id is not null and hote_id in (select h.id from bsh_hotes h where h.profile_id = auth.uid() and h.statut = 'active'));
create policy bsh_communications_hotesses on public.bsh_communications for select to authenticated using (statut = 'publie' and cible = 'hotesses' and est_hote_bsh());
create policy bsh_communications_publiques on public.bsh_communications for select to anon, authenticated using (statut = 'publie' and cible = 'tous');
create policy bsh_missions_fondatrice on public.bsh_missions for all to public using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_missions_propres on public.bsh_missions for select to authenticated using (hote_id in (select bsh_hotes.id from bsh_hotes where bsh_hotes.profile_id = auth.uid()));
create policy bsh_animations_fondatrice on public.bsh_animations for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_animations_hote_attribuee on public.bsh_animations for select to authenticated using (hote_id is not null and hote_id in (select h.id from bsh_hotes h where h.profile_id = auth.uid() and h.statut = 'active'));
create policy bsh_campagnes_fondatrice on public.bsh_campagnes for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_jeux_fondatrice on public.bsh_jeux for all to public using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_jeux_lecture_publique on public.bsh_jeux for select to anon, authenticated using (statut = 'publie');
create policy bsh_agenda_reglages_fondatrice on public.bsh_agenda_reglages for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
create policy bsh_hotes_disponibilites_fondatrice on public.bsh_hotes_disponibilites for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
create policy dispo_propres on public.bsh_hotes_disponibilites for all to authenticated using (hote_id = bsh_mon_hote()) with check (hote_id = bsh_mon_hote());
create policy bsh_rewards_campagnes_fondatrice on public.bsh_rewards_campagnes for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
create policy events_medias_fondatrice on public.events_medias for all to authenticated using (is_fondatrice()) with check (is_fondatrice());
